local Controller={};Controller.__index=Controller
local function cp(v)if type(v)~="table"then return v end;local o={};for k,x in pairs(v)do o[cp(k)]=cp(x)end;return o end
local function id(v)return type(v)=="string"and#v>0 and#v<=128 and v:match("^[%w][%w_.:%-]*$")~=nil end
local function now(self,n)if type(n)~="number"or n~=n or n<0 or n>=math.huge then return nil end;if n>self.last_now then self.last_now=n end;return self.last_now end
local function sorted_live(self,except,uninfected)local out={};for pid,p in pairs(self.players)do if pid~=except and p.alive and p.connected and(not uninfected or not p.infected)then out[#out+1]=pid end end;table.sort(out);return out end
local function signature(kind,args)local p={kind};for _,v in ipairs(args)do p[#p+1]=type(v)=="table"and table.concat(v,",")or tostring(v)end;return table.concat(p,"|")end
local function integer(v,min)return type(v)=="number"and v%1==0 and v>=min and v<math.huge end
local function finite(v)return type(v)=="number"and v==v and v>=0 and v<math.huge end
local function array(v)if type(v)~="table"then return false end;local n=0;for k in pairs(v)do if not integer(k,1)then return false end;n=n+1 end;return n==#v end
local function fields(v,a)local n=0;for k in pairs(v)do if not a[k]then return false end;n=n+1 end;return n end
local function serial(v,seen)local t=type(v);if t=="nil"or t=="string"or t=="boolean"then return true end;if t=="number"then return v==v and v<math.huge and v>-math.huge end;if t~="table"then return false end;seen=seen or{};if seen[v]then return false end;seen[v]=true;for k,x in pairs(v)do if(type(k)~="string"and type(k)~="number")or not serial(k,seen)or not serial(x,seen)then return false end end;seen[v]=nil;return true end
local function restore(self,s)
 local allowed={schema_version=1,status=1,round_id=1,variant=1,holder=1,deadline=1,object_id=1,object_revision=1,last_sequence=1,last_now=1,settlements=1,result=1,audit=1,players=1,seen=1}
 if type(s)~="table"or s.schema_version~=1 or not fields(s,allowed)or(s.status~="waiting"and s.status~="active"and s.status~="finished"and s.status~="cleanup")or s.object_id~=self.object_id or s.object_revision~=self.object_revision or not integer(s.last_sequence,0)or not finite(s.last_now)or not integer(s.settlements,0)or s.settlements>1 or type(s.players)~="table"or not array(s.audit)or type(s.seen)~="table"or not serial(s.audit)then return false end
 local count=0
 for pid,p in pairs(s.players)do count=count+1;if not id(pid)or type(p)~="table"or fields(p,{revision=1,alive=1,connected=1,infected=1})~=4 or not integer(p.revision,1)or type(p.alive)~="boolean"or type(p.connected)~="boolean"or type(p.infected)~="boolean"then return false end end
 for eid,e in pairs(s.seen)do if not id(eid)or type(e)~="table"or fields(e,{key=1,ok=1,code=1,data=1})~=4 or type(e.key)~="string"or e.key==""or type(e.ok)~="boolean"or type(e.code)~="string"or e.code==""or type(e.data)~="table"or not serial(e.data)then return false end end
 if s.status=="waiting"then if count~=0 or s.round_id~=nil or s.variant~=nil or s.holder~=nil or s.deadline~=nil or s.result~=nil or s.settlements~=0 then return false end
 else if count~=3 or not id(s.round_id)or(s.variant~="exploding"and s.variant~="infectious")or not finite(s.deadline)then return false end;if s.status=="active"then if not id(s.holder)or not s.players[s.holder]or s.result~=nil or s.settlements~=0 or s.last_now>=s.deadline then return false end else if(s.holder~=nil and(not id(s.holder)or not s.players[s.holder]))or type(s.result)~="table"or s.settlements~=1 or s.result.variant~=s.variant or s.result.holder~=s.holder or not array(s.result.eliminated)or not array(s.result.winners)or not finite(s.result.settled_at)then return false end;local winners={};for _,pid in ipairs(s.result.winners)do if not id(pid)or winners[pid]or not s.players[pid]or not s.players[pid].alive or not s.players[pid].connected or pid==s.holder or(s.variant=="infectious"and s.players[pid].infected)then return false end;winners[pid]=true end end end
 for _,a in ipairs(s.audit)do if type(a)~="table"or type(a.type)~="string"or not finite(a.at)or a.at>s.last_now then return false end end
 for k,v in pairs(s)do if k~="schema_version"then self[k]=cp(v)end end;return true
end
function Controller.new(o)o=o or{};local oid=o.object_id or"hot:1";local orev=o.object_revision or 1;if not id(oid)or type(orev)~="number"or orev<1 or orev%1~=0 then return nil,"invalid_options"end;local self=setmetatable({status="waiting",object_id=oid,object_revision=orev,players={},seen={},audit={},last_sequence=0,last_now=0,settlements=0,stopped=false},Controller);local s=o.state;if s and not restore(self,s)then return nil,"invalid_state"end;return self end
function Controller:_event(eid,kind,args)if not id(eid)then return false,"invalid_event",{}end;local k=signature(kind,args);local old=self.seen[eid];if old then if old.key~=k then return false,"event_conflict",{}end;return old.ok,old.code,cp(old.data)end;return nil,k end
function Controller:_done(eid,k,ok,code,data)self.seen[eid]={key=k,ok=ok,code=code,data=cp(data or{})};return ok,code,cp(data or{})end
function Controller:start(rid,round_id,variant,players,holder,deadline)if self.stopped then return false,"shutdown",{}end;local old,k,d=self:_event(rid,"start",{round_id,variant,players,holder,deadline});if old~=nil then return old,k,d end;if self.status~="waiting"or not id(round_id)or(variant~="exploding"and variant~="infectious")or not array(players)or#players~=3 or not id(holder)or not finite(deadline)or deadline<=self.last_now then return self:_done(rid,k,false,"invalid_round",{})end;local seen={};for _,p in ipairs(players)do if not id(p)or seen[p]then return self:_done(rid,k,false,"invalid_players",{})end;seen[p]=true;self.players[p]={revision=1,alive=true,connected=true,infected=false}end;if not self.players[holder]then return self:_done(rid,k,false,"invalid_holder",{})end;self.round_id=round_id;self.variant=variant;self.holder=holder;self.deadline=deadline;self.status="active";self.audit[#self.audit+1]={type="active",at=self.last_now};return self:_done(rid,k,true,"started",{holder=holder})end
function Controller:touch(eid,oid,orev,pid,prev,seq,t)if self.stopped then return false,"shutdown",{}end;local args={oid,orev,pid,prev,seq,t};local old,k,d=self:_event(eid,"touch",args);if old~=nil then return old,k,d end;local effective=now(self,t);if not effective then return false,"invalid_time",{}end;if self.status~="active"or effective>=self.deadline then self:tick(effective);return self:_done(eid,k,false,"round_closed",{})end;local p=self.players[pid];if oid~=self.object_id or orev~=self.object_revision then return self:_done(eid,k,false,"wrong_object",{})end;if not p or p.revision~=prev or not p.alive or not p.connected then return self:_done(eid,k,false,"invalid_player",{})end;if type(seq)~="number"or seq%1~=0 or seq<=self.last_sequence then return self:_done(eid,k,false,"stale_sequence",{})end;self.last_sequence=seq;local prior=self.holder;self.holder=pid;if self.variant=="infectious"then p.infected=true end;local data={from=prior,to=pid,sequence=seq};self.audit[#self.audit+1]={type="touch",at=effective,sequence=seq,from=prior,to=pid};return self:_done(eid,k,true,"transferred",data)end
function Controller:_lose(eid,kind,pid,rev,t)local old,k,d=self:_event(eid,kind,{pid,rev,t});if old~=nil then return old,k,d end;local effective=now(self,t);local p=self.players[pid];if not effective or not p or p.revision~=rev then return self:_done(eid,k,false,"invalid_player",{})end;if kind=="death"then p.alive=false else p.connected=false end;if self.holder==pid then local nexts=sorted_live(self,pid);self.holder=nexts[1];if not self.holder then self:_settle(kind,effective)end end;self.audit[#self.audit+1]={type=kind,at=effective,player_id=pid};return self:_done(eid,k,true,kind,{holder=self.holder})end
function Controller:death(...)return self:_lose(select(1,...),"death",select(2,...))end
function Controller:disconnect(...)return self:_lose(select(1,...),"disconnect",select(2,...))end
function Controller:respawn(eid,pid,old_revision,new_revision,t)
 local old,k,d=self:_event(eid,"respawn",{pid,old_revision,new_revision,t});if old~=nil then return old,k,d end;local effective=now(self,t);local p=self.players[pid]
 if not effective or not p or p.revision~=old_revision or not integer(new_revision,1)or new_revision<=old_revision then return self:_done(eid,k,false,"invalid_player",{})end
 p.revision=new_revision;p.alive=true;p.connected=true;self.audit[#self.audit+1]={type="respawn",at=effective,player_id=pid,revision=new_revision};return self:_done(eid,k,true,"respawned",{revision=new_revision})
end
function Controller:_settle(reason,t)if self.status~="active"then return end;self.status="resolving";local holder=self.holder;local eliminated={};if holder then eliminated[1]=holder;if self.variant=="infectious"and self.players[holder]then self.players[holder].infected=true end end;local winners=sorted_live(self,holder,self.variant=="infectious");self.result={reason=reason,holder=holder,eliminated=eliminated,winners=winners,variant=self.variant,settled_at=t};self.settlements=self.settlements+1;self.audit[#self.audit+1]={type="resolving",at=t};self.status="finished";self.audit[#self.audit+1]={type="finished",at=t}end
function Controller:tick(t)if self.stopped then return false,"shutdown",{}end;local effective=now(self,t);if not effective then return false,"invalid_time",{}end;if self.status=="active"and effective>=self.deadline then self:_settle("deadline",effective)elseif self.status=="finished"and effective>=self.deadline+1 then self.status="cleanup";self.audit[#self.audit+1]={type="cleanup",at=effective}end;return true,"ticked",{status=self.status,settlements=self.settlements}
end
function Controller:snapshot(t)if t~=nil then self:tick(t)end;local out={schema_version=1,status=self.status,round_id=self.round_id,variant=self.variant,holder=self.holder,deadline=self.deadline,object_id=self.object_id,object_revision=self.object_revision,last_sequence=self.last_sequence,last_now=self.last_now,settlements=self.settlements,result=cp(self.result),audit=cp(self.audit),players=cp(self.players)};return out end
function Controller:save(t)local s=self:snapshot(t);s.seen=cp(self.seen);return s end
function Controller:shutdown()self.stopped=true;return true,"shutdown"end;return Controller
